(()=>{const links=[...document.querySelectorAll('.product-nav a')];document.querySelectorAll('[data-contact]').forEach(b=>b.addEventListener('click',()=>parent.postMessage({namespace:'ctuav-demo',type:'route',route:'contact',line:'06 Drone Light Show'},'*')));links.forEach(a=>a.addEventListener('click',e=>{const el=document.querySelector(a.hash);if(!el)return;e.preventDefault();el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}));addEventListener('message',e=>{if(e.source!==parent||e.data?.namespace!=='ctuav-demo')return;if(e.data.type==='view-active'&&e.data.active)scrollTo(0,0)});})();(()=>{const links=[...document.querySelectorAll('.product-nav a')];const update=()=>{let active=links[0];for(const a of links){const section=document.querySelector(a.hash);if(section&&section.getBoundingClientRect().top<180)active=a}for(const a of links){if(a===active)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')}};addEventListener('scroll',update,{passive:true});addEventListener('resize',update);update()})();(()=>{const b=document.querySelector(".product-bar");new ResizeObserver(()=>document.documentElement.style.setProperty("--glova-bar-height",b.offsetHeight+"px")).observe(b)})();